@Composable private fun Message(p:ExcelReaderPhase,pad:PaddingValues,back:()->Unit,retry:()->Unit){val msg=when(p){ExcelReaderPhase.UnsupportedFormat->"This spreadsheet format is not supported.";ExcelReaderPhase.PasswordProtected->"Password-protected spreadsheets are not supported yet.";ExcelReaderPhase.MissingFile->"This spreadsheet may have been moved or deleted.";ExcelReaderPhase.PermissionDenied->"Access to this spreadsheet is no longer available.";ExcelReaderPhase.RendererProcessCrashed->"The spreadsheet renderer stopped.";ExcelReaderPhase.ParseTimeout->"The workbook took too long to parse.";ExcelReaderPhase.EmptyWorkbook->"This spreadsheet contains no worksheets.";ExcelReaderPhase.FileTooLarge->"This spreadsheet is too large to open safely.";ExcelReaderPhase.SafetyLimit->"This spreadsheet exceeds safe processing limits.";ExcelReaderPhase.Corrupted->"This spreadsheet appears to be corrupted.";ExcelReaderPhase.WebViewUnavailable->"Android System WebView is unavailable.";else->"The spreadsheet viewer could not process this file."};Column(Modifier.fillMaxSize().padding(pad).padding(32.dp),Arrangement.Center,Alignment.CenterHorizontally){Icon(Icons.Outlined.TableChart,null,Modifier.size(52.dp));Text(msg);Row{TextButton(onClick=back){Text("Back")};if(p in setOf(ExcelReaderPhase.MissingFile,ExcelReaderPhase.PermissionDenied,ExcelReaderPhase.RendererProcessCrashed,ExcelReaderPhase.ParseTimeout,ExcelReaderPhase.ParseFailure))Button(onClick=retry){Text("Retry")}}}}
